(()=>{
  const script=document.currentScript;if(!script)return;
  const base=new URL(script.src).origin,tenant=script.dataset.tenant||'care-beyond';
  if(document.querySelector('[data-care-beyond-widget]'))return;
  const host=document.createElement('div');host.dataset.careBeyondWidget='';document.body.append(host);const shadow=host.attachShadow({mode:'open'});
  const css=document.createElement('style');css.textContent=':host{all:initial}button{font-family:Arial,sans-serif;cursor:pointer}.launcher{position:fixed;right:24px;bottom:24px;z-index:2147483000;border:0;border-radius:32px;background:#195e61;color:white;padding:16px 23px;box-shadow:0 7px 26px #173d4930;font-size:14px;display:flex;align-items:center;gap:12px;min-height:55px}.launcher svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.8}.launcher:focus-visible{outline:3px solid #b89bdd;outline-offset:4px}.frame{position:fixed;right:24px;bottom:92px;width:400px;height:min(680px,calc(100dvh - 120px));max-width:calc(100vw - 32px);z-index:2147483000;border:1px solid #dce4df;border-radius:22px;background:white;box-shadow:0 12px 60px #1b404336;overflow:hidden}.frame iframe{border:0;width:100%;height:100%}[hidden]{display:none!important}@media(max-width:480px){.frame{right:12px;bottom:88px;width:calc(100vw - 24px);height:calc(100dvh - 110px);max-width:none}.launcher{right:16px;bottom:17px;padding:14px 18px;font-size:13px}}';
  const button=document.createElement('button');button.className='launcher';button.type='button';button.setAttribute('aria-label','Open Care Beyond support assistant');button.setAttribute('aria-expanded','false');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 11a9 9 0 0 1-9 9H4l-3 2v-9a9 9 0 0 1 9-9h2a9 9 0 0 1 9 7Z"/><path d="M7 11h10M7 15h6"/></svg><span>Ask a question</span>';
  const panel=document.createElement('div');panel.className='frame';panel.hidden=true;const frame=document.createElement('iframe');frame.title='Care Beyond Expectations support assistant';frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms allow-popups allow-top-navigation-by-user-activation');panel.append(frame);shadow.append(css,panel,button);
  function close(){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus();}
  button.addEventListener('click',()=>{const open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));if(open&&!frame.src)frame.src=base+'/widget.html?tenant='+encodeURIComponent(tenant)+'&parentOrigin='+encodeURIComponent(location.origin);if(open)frame.focus();});
  window.addEventListener('message',e=>{if(e.origin===base&&e.source===frame.contentWindow&&e.data?.type==='care-beyond-close')close();});
  window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)close();});
})();
